import React from 'react';
import Reveal from './Reveal';
import './Projects.css';
const TECH_STACK=['Java','SQL','HTML','CSS'];
function Projects(){return <section id="projects" className="section projects"><div className="container"><div className="section-header"><Reveal><p className="eyebrow">/ Selected Work</p><h2 className="section-title">One project. Real problem.</h2></Reveal><Reveal delay={100}><p className="section-sub">A practical academic project focused on reducing food wastage and improving inventory visibility through software.</p></Reveal></div><Reveal className="project-card"><div className="project-card-content"><div className="project-info"><span className="badge">01 / Academic Project</span><h3 className="project-title">Smart Mess and Inventory Management System</h3><p className="project-desc">Developed a Smart Mess and Inventory Management System to streamline meal planning, inventory tracking, and food stock management. The system helps maintain accurate inventory records, reduces food wastage through efficient stock monitoring, and improves the overall management process.</p><div className="project-tech">{TECH_STACK.map(t=><span key={t} className="badge project-badge">{t}</span>)}</div><div className="project-actions"><a href="https://github.com/your-github-username/smart-mess-inventory" target="_blank" rel="noreferrer" className="btn btn-outline">View on GitHub ↗</a><a href="https://your-live-demo-link.example.com" target="_blank" rel="noreferrer" className="btn btn-primary">Live Demo ↗</a></div></div><div className="project-visual"><div className="project-visual-grid"><span>Inventory</span><span>Meal Planning</span><span>Stock Alerts</span><span>Reports</span></div></div></div></Reveal></div></section>}
export default Projects;
